INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 11, 0, 0.5, 311, 0, 100911, 311006, 0, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！", 8);
